package com.neobank.customer.controller;
import com.neobank.customer.domain.*; import com.neobank.customer.service.CustomerService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/v1") public class CustomerController {
 private final CustomerService service; public CustomerController(CustomerService s){service=s;}
 public record ProfileRequest(@NotBlank @Size(max=120) String fullName,@Email @Size(max=254) String email,@Size(max=30) String phone){}
 public record ProfileResponse(UUID userId,String fullName,String email,String phone,KycStatus kycStatus,KycTier kycTier,java.time.Instant updatedAt){static ProfileResponse of(CustomerProfile p){return new ProfileResponse(p.getUserId(),p.getFullName(),p.getEmail(),p.getPhone(),p.getKycStatus(),p.getKycTier(),p.getUpdatedAt());}}
 public record DocumentResponse(UUID id,String documentType,String fileName,String contentType,long fileSize,java.time.Instant uploadedAt){static DocumentResponse of(KycDocument d){return new DocumentResponse(d.getId(),d.getDocumentType(),d.getFileName(),d.getContentType(),d.getFileSize(),d.getUploadedAt());}}
 private UUID uid(Jwt jwt){return UUID.fromString(jwt.getSubject());} private void admin(Jwt jwt){if(!"ADMIN".equals(jwt.getClaimAsString("role")))throw new AccessDeniedException("ADMIN role required");}
 @GetMapping("/customers/me") public ProfileResponse profile(@AuthenticationPrincipal Jwt jwt){return ProfileResponse.of(service.getOrCreate(uid(jwt),jwt.getClaimAsString("name")));}
 @PutMapping("/customers/me") public ProfileResponse update(@Valid @RequestBody ProfileRequest r,@AuthenticationPrincipal Jwt jwt){return ProfileResponse.of(service.update(uid(jwt),r.fullName(),r.email(),r.phone()));}
 @GetMapping("/kyc/status") public ProfileResponse status(@AuthenticationPrincipal Jwt jwt){return profile(jwt);}
 @PostMapping(value="/kyc/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<DocumentResponse> upload(@RequestParam @NotBlank @Size(max=40) String documentType,@RequestPart MultipartFile file,@AuthenticationPrincipal Jwt jwt)throws java.io.IOException{return ResponseEntity.status(HttpStatus.CREATED).body(DocumentResponse.of(service.upload(uid(jwt),documentType,file)));}
 @GetMapping("/kyc/documents") public List<DocumentResponse> documents(@AuthenticationPrincipal Jwt jwt){return service.documents(uid(jwt)).stream().map(DocumentResponse::of).toList();}
 @GetMapping("/kyc/documents/{id}/content") public ResponseEntity<byte[]> content(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){KycDocument d=service.document(uid(jwt),id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(d.getFileName()).build().toString()).body(d.getContent());}
 @PostMapping("/kyc/submit") public ProfileResponse submit(@AuthenticationPrincipal Jwt jwt){return ProfileResponse.of(service.submit(uid(jwt)));}
 @PostMapping("/admin/customers/{userId}/kyc/review") public ProfileResponse review(@PathVariable UUID userId,@RequestParam KycStatus status,@RequestParam(defaultValue="BASIC") KycTier tier,@AuthenticationPrincipal Jwt jwt){admin(jwt);return ProfileResponse.of(service.review(userId,status,tier));}
}